css:
.files {
  max-width: 40rem;
  margin: 0 auto;
  padding: var(--va-space-inline-lg);
  font-family: var(--va-font-family-ui);
  color: var(--va-color-text-default);
}

.files__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--va-space-inline-md);
  margin-block-end: var(--va-space-inline-md);
}

.files__header h1 {
  margin: 0;
  font-family: var(--va-font-family-reading);
  font-size: var(--va-font-size-lg);
  font-weight: var(--va-font-weight-bold);
}

.files__header h1:focus-visible {
  outline: var(--va-size-focus-ring) solid var(--va-color-focus);
  outline-offset: var(--va-size-focus-ring);
  border-radius: var(--va-radius-control);
}

.files__count,
.files__empty {
  margin: 0;
  font-size: var(--va-font-size-sm);
  color: var(--va-color-text-muted);
}

.files__list {
  list-style: none;
  margin: 0;
  padding: 0;
  border: 1px solid var(--va-color-border-subtle);
  border-radius: var(--va-radius-surface);
  background: var(--va-color-surface-default);
}

.files__list:empty {
  display: none;
}

.file {
  display: flex;
  align-items: center;
  gap: var(--va-space-inline-md);
  padding: var(--va-space-inline-md) var(--va-space-inline-lg);
}

.file + .file {
  border-block-start: 1px solid var(--va-color-border-subtle);
}

.file__icon {
  flex: none;
  inline-size: 1.5rem;
  block-size: 1.5rem;
  color: var(--va-color-text-muted);
}

.file__text {
  flex: 1;
  min-inline-size: 0;
  display: flex;
  flex-direction: column;
  gap: var(--va-space-gap-sm);
}

.file__name {
  font-size: var(--va-font-size-md);
  font-weight: var(--va-font-weight-medium);
  overflow-wrap: anywhere;
}

.file__meta {
  font-size: var(--va-font-size-sm);
  color: var(--va-color-text-muted);
}

.files__empty {
  padding: var(--va-space-inline-lg);
  border: 1px dashed var(--va-color-border-subtle);
  border-radius: var(--va-radius-surface);
  text-align: center;
}

js:
const list = document.getElementById('file-list');
const heading = document.getElementById('files-heading');
const count = document.getElementById('files-count');
const empty = document.getElementById('files-empty');
const toaster = document.getElementById('toaster');

const renameForm = document.getElementById('rename-form');
const renameDialog = document.getElementById('rename-dialog');
const renameField = document.getElementById('rename-field');

const deleteDialog = document.getElementById('delete-dialog');
const deleteName = document.getElementById('delete-name');
const deleteConfirm = document.getElementById('delete-confirm');

/** The row the open dialog acts on. */
let current = null;

const nameOf = (row) => row.dataset.file;

function setName(row, name) {
  row.dataset.file = name;
  row.querySelector('.file__name').textContent = name;
}

function updateCount() {
  const n = list.querySelectorAll('.file').length;
  count.textContent = n === 1 ? '1 file' : `${n} files`;
  empty.hidden = n > 0;
}

function notify(message, variant) {
  if (variant) toaster.show(message, { variant });
  else toaster.show(message);
}

/* ---------- Menu actions ---------- */

list.addEventListener('va-select', (event) => {
  const row = event.target.closest('.file');
  if (!row) return;
  current = row;

  switch (event.detail.value) {
    case 'rename':
      renameField.error = '';
      renameField.value = nameOf(row);
      renameDialog.heading = `Rename ${nameOf(row)}`;
      renameDialog.show();
      break;
    case 'download':
      notify(`Downloading ${nameOf(row)}`);
      break;
    case 'delete':
      deleteName.textContent = nameOf(row);
      deleteDialog.heading = `Delete ${nameOf(row)}?`;
      deleteDialog.show();
      break;
  }
});

/* ---------- Rename ---------- */

function validateName(name) {
  if (!name) return 'Enter a file name.';
  if (/[\\/]/.test(name)) return 'A file name can’t contain / or \\.';
  const taken = [...list.querySelectorAll('.file')].some(
    (row) => row !== current && nameOf(row).toLowerCase() === name.toLowerCase(),
  );
  if (taken) return 'A file with this name already exists.';
  return '';
}

renameField.addEventListener('input', () => {
  if (renameField.error) renameField.error = '';
});

renameField.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    renameForm.requestSubmit();
  }
});

renameForm.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!current || !renameDialog.open) return;

  const name = renameField.value.trim();
  const error = validateName(name);
  if (error) {
    renameField.error = error;
    renameField.focus();
    return;
  }

  const old = nameOf(current);
  renameDialog.close();
  if (name !== old) {
    setName(current, name);
    notify(`Renamed ${old} to ${name}`, 'success');
  }
});

/* ---------- Delete ---------- */

deleteConfirm.addEventListener('click', () => {
  if (!current) return;
  const row = current;
  const name = nameOf(row);
  current = null;

  deleteDialog.close();
  row.remove();
  updateCount();
  notify(`Deleted ${name}`, 'success');

  // The row's Actions button is gone, so move focus to the list heading
  // after the dialog has finished restoring focus.
  requestAnimationFrame(() => heading.focus());
});

updateCount();
